package com.nexusplay.player;
import android.Manifest; import android.content.ContentUris; import android.content.Intent; import android.content.pm.PackageManager; import android.database.Cursor; import android.net.Uri; import android.os.Build; import android.os.Bundle; import android.provider.MediaStore; import android.text.Editable; import android.text.TextWatcher; import android.view.Gravity; import android.widget.EditText; import android.widget.LinearLayout; import android.widget.ScrollView; import android.widget.TextView; import android.graphics.drawable.GradientDrawable; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.appcompat.app.AppCompatActivity; import androidx.core.content.ContextCompat; import java.util.ArrayList; import java.util.Locale;
public class MainActivity extends AppCompatActivity {
 private final ArrayList<Video> videos=new ArrayList<>(); private LinearLayout list; private EditText search; private TextView count; private String tab="All videos"; private final int bg=0xFF0B0D14,panel=0xFF151925,muted=0xFF8B91A6,white=0xFFF5F6FC,mint=0xFF4DE1C1; private ActivityResultLauncher<String> permissionRequest;
 static class Video { String title,filename,folder,duration,size; Uri uri; Video(String t,String f,String fo,String d,String s,Uri u){title=t;filename=f;folder=fo;duration=d;size=s;uri=u;} }
 @Override protected void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);permissionRequest=registerForActivityResult(new ActivityResultContracts.RequestPermission(),ok->{if(ok)loadVideos();else emptyMessage("Allow video access in Android settings to browse your library.");});buildUi();if(hasPermission())loadVideos();else requestPermission();}
 private boolean hasPermission(){String p=Build.VERSION.SDK_INT>=33?Manifest.permission.READ_MEDIA_VIDEO:Manifest.permission.READ_EXTERNAL_STORAGE;return ContextCompat.checkSelfPermission(this,p)==PackageManager.PERMISSION_GRANTED;}
 private void requestPermission(){permissionRequest.launch(Build.VERSION.SDK_INT>=33?Manifest.permission.READ_MEDIA_VIDEO:Manifest.permission.READ_EXTERNAL_STORAGE);}
 private void buildUi(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(12),dp(20),0);root.setBackgroundColor(bg);TextView brand=label("N E X U S P L A Y",12,mint,true);root.addView(brand,lp(-1,dp(28)));TextView heading=label("Your videos,\nyour space.",30,white,true);root.addView(heading,lp(-1,dp(82)));root.addView(label("A clean, private player for your library.",14,muted,false),lp(-1,dp(30)));
 search=new EditText(this);search.setSingleLine(true);search.setTextSize(15);search.setTextColor(white);search.setHintTextColor(muted);search.setHint("Search videos or folders");search.setPadding(dp(16),0,dp(16),0);search.setBackground(round(panel,dp(16)));root.addView(search,lp(-1,dp(52)));
 LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(0);tabs.setPadding(0,dp(14),0,dp(10));for(String name:new String[]{"All videos","Folders","Recent"}){TextView t=label(name,13,name.equals(tab)?bg:muted,true);t.setGravity(Gravity.CENTER);t.setBackground(round(name.equals(tab)?mint:panel,dp(20)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(38),1);p.setMargins(0,0,dp(7),0);tabs.addView(t,p);t.setOnClickListener(v->{tab=name;buildUi();render();});}root.addView(tabs,lp(-1,dp(52)));
 count=label("YOUR LIBRARY",12,muted,true);root.addView(count,lp(-1,dp(28)));ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);list.setPadding(0,dp(4),0,dp(20));scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView footer=label("LOCAL ONLY  •  NO ADS  •  NO TRACKING",10,muted,true);footer.setGravity(Gravity.CENTER);root.addView(footer,lp(-1,dp(38)));setContentView(root);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int c){render();}public void afterTextChanged(Editable e){}});}
 private void loadVideos(){videos.clear();Uri collection=Build.VERSION.SDK_INT>=29?MediaStore.Video.Media.getContentUri(MediaStore.VOLUME_EXTERNAL):MediaStore.Video.Media.EXTERNAL_CONTENT_URI;String[] cols={MediaStore.Video.Media._ID,MediaStore.Video.Media.TITLE,MediaStore.Video.Media.DISPLAY_NAME,MediaStore.Video.Media.DURATION,MediaStore.Video.Media.SIZE,MediaStore.Video.Media.RELATIVE_PATH};try(Cursor c=getContentResolver().query(collection,cols,null,null,MediaStore.Video.Media.DATE_ADDED+" DESC")){if(c!=null)while(c.moveToNext()){long id=c.getLong(0),ms=c.getLong(3),bytes=c.getLong(4);String title=c.getString(1),filename=c.getString(2),folder=c.getString(5);if(title==null||title.trim().isEmpty())title=filename;if(folder==null)folder="Videos";videos.add(new Video(title,filename,folder,duration(ms),size(bytes),ContentUris.withAppendedId(collection,id)));}}catch(Exception e){emptyMessage("Could not read the video library. Check media access.");}render();}
 private void render(){if(list==null)return;list.removeAllViews();String q=search==null?"":search.getText().toString().toLowerCase(Locale.ROOT).trim();ArrayList<Video> shown=new ArrayList<>();for(Video v:videos){if(!(v.title.toLowerCase(Locale.ROOT).contains(q)||v.filename.toLowerCase(Locale.ROOT).contains(q)||v.folder.toLowerCase(Locale.ROOT).contains(q)))continue;if(tab.equals("Folders")){boolean seen=false;for(Video old:shown)if(old.folder.equals(v.folder)){seen=true;break;}if(!seen)shown.add(v);}else shown.add(v);}count.setText(tab.equals("Folders")?shown.size()+" FOLDERS":shown.size()+" VIDEOS");if(shown.isEmpty()){emptyMessage(videos.isEmpty()?"No videos found yet.\nAdd videos to your device and allow library access.":"No matches. Try another search.");return;}for(Video v:shown){LinearLayout card=new LinearLayout(this);card.setOrientation(0);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setBackground(round(panel,dp(18)));LinearLayout.LayoutParams cp=lp(-1,dp(84));cp.setMargins(0,0,0,dp(10));list.addView(card,cp);TextView icon=label(tab.equals("Folders")?"▰":"▶",20,mint,true);icon.setGravity(Gravity.CENTER);icon.setBackground(round(0xFF24213A,dp(14)));card.addView(icon,lp(dp(54),dp(54)));LinearLayout info=new LinearLayout(this);info.setOrientation(1);info.setPadding(dp(12),0,dp(4),0);card.addView(info,new LinearLayout.LayoutParams(0,-2,1));TextView title=label(tab.equals("Folders")?v.folder:v.title,14,white,true);title.setMaxLines(2);info.addView(title,lp(-1,-2));info.addView(label(tab.equals("Folders")?"Tap to filter folder":v.duration+"  •  "+v.size,12,muted,false),lp(-1,dp(24)));card.setOnClickListener(view->{if(tab.equals("Folders")){tab="All videos";search.setText(v.folder);render();}else{Intent i=new Intent(this,PlayerActivity.class);i.setData(v.uri);i.putExtra("title",v.title);startActivity(i);}});}}
 private void emptyMessage(String m){if(list==null)return;list.removeAllViews();TextView t=label(m,15,muted,false);t.setGravity(Gravity.CENTER);t.setPadding(dp(18),dp(30),dp(18),dp(30));list.addView(t,lp(-1,dp(160)));}
 private TextView label(String s,float size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,android.graphics.Typeface.BOLD);return t;}private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}private LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w,h);}private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}private String duration(long ms){long s=ms/1000;return String.format(Locale.ROOT,"%02d:%02d:%02d",s/3600,(s%3600)/60,s%60);}private String size(long b){if(b>=1073741824L)return String.format(Locale.ROOT,"%.1f GB",b/1073741824d);if(b>=1048576L)return String.format(Locale.ROOT,"%.0f MB",b/1048576d);return Math.max(1,b/1024)+" KB";}
}
